export type PageKind = "standings" | "live" | "lineup" | "draft" | "draft-recap" | "rundown" | "news" | "transactions" | "trades" | "free-agents" | "results" | "history" | "playoffs" | "rules" | "nfl-sites" | "rosters" | "money" | "settings" | "player";

const pageMeta: Record<PageKind, { eyebrow: string; title: string; detail: string; icon: React.ElementType }> = {
  standings: { eyebrow: "League table", title: "Standings", detail: "The current competitive picture, driven by CVC-configured records, divisions, and tiebreakers.", icon: Trophy },
  live: { eyebrow: "Game center", title: "Live scoring", detail: "A provider-neutral scoring surface that will connect to the CVC NFL data adapter once a source is selected.", icon: Radio },
  lineup: { eyebrow: "Owner workspace", title: "My lineup", detail: "Set starters, manage your roster, and review matchup projections in one secure owner view.", icon: ClipboardList },
  draft: { eyebrow: "Draft room", title: "Draft hub", detail: "Configuration-ready draft board, pick ownership, protections, and timing controls.", icon: Gavel },
  "draft-recap": { eyebrow: "Draft room", title: "Draft recap", detail: "Review selections, traded picks, and post-draft outcomes across CVC seasons.", icon: FileText },
  rundown: { eyebrow: "League desk", title: "Commissioner rundown", detail: "A polished landing area for league updates, weekly context, and key deadlines.", icon: Newspaper },
  news: { eyebrow: "Player desk", title: "Player news", detail: "A source-agnostic player news surface with provider attribution ready to be configured.", icon: Activity },
  transactions: { eyebrow: "League ledger", title: "Transactions", detail: "Every addition, drop, waiver award, commissioner correction, and roster move in one audit-friendly feed.", icon: ReceiptText },
  trades: { eyebrow: "Trade desk", title: "Trades", detail: "Review trade proposals, approval state, assets, deadlines, and commissioner decisions.", icon: Scale },
  "free-agents": { eyebrow: "Player pool", title: "Free agents & FAAB", detail: "A configurable claim and bid workflow designed around CVC waiver rules and budget settings.", icon: BadgeDollarSign },
  results: { eyebrow: "Scoreboard", title: "Schedule & results", detail: "League weeks, matchup outcomes, and schedule structure ready for commissioner import.", icon: CalendarDays },
  history: { eyebrow: "Archive", title: "League history", detail: "A permanent home for champions, records, prior seasons, and memorable CVC moments.", icon: BookOpen },
  playoffs: { eyebrow: "Postseason", title: "Playoffs", detail: "A configurable playoff bracket with seeding, matchup, and tiebreaker support.", icon: Crown },
  rules: { eyebrow: "League governance", title: "Rules & policies", detail: "Versioned CVC rules documents will publish directly from commissioner-managed content.", icon: ShieldCheck },
  "nfl-sites": { eyebrow: "Reference desk", title: "NFL sites", detail: "Commissioner-curated reference links, data-source acknowledgements, and league resources.", icon: ListFilter },
  rosters: { eyebrow: "Franchises", title: "Rosters", detail: "Explore every CVC franchise, owner identity, roster build, and weekly status.", icon: UsersRound },
  money: { eyebrow: "League office", title: "League finance", detail: "A private league-ledger view for dues, payouts, balances, and commissioner financial notes.", icon: WalletCards },
  settings: { eyebrow: "Commissioner office", title: "League configuration", detail: "Set up CVC teams, owners, scoring, schedule, rules, and financial settings without code changes.", icon: Settings2 },
  player: { eyebrow: "Player profile", title: "Player detail", detail: "A reusable player profile for current status, scoring, news, game logs, and roster availability.", icon: Activity },
};

pageMeta.live.detail = "A current-week-only, Tank01-powered game center with WRC-style head-to-head lineups and automatic CVC scoring.";

function PageHeader({ kind, action }: { kind: PageKind; action?: React.ReactNode }) {
  const meta = pageMeta[kind];
  const Icon = meta.icon;
  return <div className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><div className="cvc-eyebrow"><Icon size={14} /> {meta.eyebrow}</div><h1 className="mt-2 font-display text-5xl uppercase leading-none tracking-[0.04em] text-white sm:text-6xl">{meta.title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-cvc-muted">{meta.detail}</p></div>{action}</div>;
}

function Card({ title, children, action, className }: { title?: string; children: React.ReactNode; action?: React.ReactNode; className?: string }) {
  return <section className={cn("cvc-card", className)}>{title ? <div className="cvc-card-title"><span>{title}</span>{action}</div> : null}<div className="cvc-card-stripe" /><div className="cvc-card-body">{children}</div></section>;
}

function StatusPill({ state }: { state: string }) { return <span className={cn("cvc-pill", state.toLowerCase())}>{state}</span>; }

function Standings() {
  const overview = trpc.league.overview.useQuery();
  const { owner } = useCvcOwnerAuth();
  const liveFranchises = overview.data?.franchises ?? [];
  const divisions = new Set(liveFranchises.map(team => team.division_name).filter(Boolean));
  const ownerFranchiseId = owner?.franchise?.id;
  const matchupSelection = selectCvcStandingsMatchup(overview.data?.matchups ?? [], ownerFranchiseId);
  const nextMatchup = matchupSelection.matchup;
  const orderedDivisions = ["East", "West", ...Array.from(divisions).filter(division => division !== "East" && division !== "West")];
  const completedGames = overview.data?.matchups.filter(matchup => matchup.result_state === "final").length ?? 0;
  const seasonYear = overview.data?.season?.year ?? 2026;
  const divisionTable = (divisionName: string) => {
    const teams = liveFranchises.filter(team => team.division_name === divisionName);
    if (!teams.length) return null;
    return <section key={divisionName} className="overflow-hidden rounded-xl border border-[#2d5c3c] bg-white shadow-[0_8px_24px_rgba(0,0,0,0.18)]"><div className="h-1 bg-[#dcae37]"/><div className="bg-[#003b19] px-4 py-3 font-display text-lg uppercase tracking-[0.08em] text-white sm:px-5">{divisionName} Division</div><div className="overflow-x-auto"><table className="min-w-[830px] w-full text-left text-sm text-cvc-deep"><thead className="bg-[#002d13] text-[10px] font-black uppercase tracking-[0.06em] text-white"><tr><th rowSpan={2} className="w-10 px-3 py-3 text-center">#</th><th rowSpan={2} className="min-w-56 px-3 py-3">Team</th><th rowSpan={2} className="border-l border-white/20 px-3 py-3 text-center">W</th><th rowSpan={2} className="px-3 py-3 text-center">L</th><th rowSpan={2} className="px-3 py-3 text-center">GB</th><th colSpan={2} className="border-l border-white/20 px-3 py-2 text-center">Division</th><th rowSpan={2} className="border-l border-white/20 px-3 py-3 text-center text-[#efc650]">FPTS</th><th rowSpan={2} className="border-l border-white/20 px-3 py-3 text-center">FA</th><th rowSpan={2} className="px-3 py-3 text-center">Streak</th></tr><tr><th className="border-l border-white/20 px-2 pb-3 text-center">W</th><th className="px-2 pb-3 text-center">L</th></tr></thead><tbody>{teams.map((team, index) => { const [divisionWins, divisionLosses] = String(team.divisionRecord ?? "0–0").split("–"); return <tr key={team.id} className="border-b border-slate-200 last:border-b-0 hover:bg-[#f4faef]"><td className="px-3 py-2 text-center text-slate-500">{index + 1}</td><td className="px-3 py-2"><div className="flex items-center gap-2"><TeamLogo name={team.name} abbreviation={team.abbreviation} logoUrl={team.logo_url} size="sm" className="rounded-md border-slate-200"/><div><Link href={`/lineup/${team.id}`} className="font-semibold text-cvc-deep underline decoration-cvc-accent/70 underline-offset-2 hover:text-cvc-accent">{team.name}</Link><p className="text-[11px] text-slate-500">{team.owner}</p></div></div></td><td className="border-l border-[#cde0d0] px-3 py-2 text-center font-semibold">{team.wins ?? 0}</td><td className="px-3 py-2 text-center font-semibold">{team.losses ?? 0}</td><td className="px-3 py-2 text-center text-slate-500">{Number(team.gamesBack ?? 0) === 0 ? "—" : Number(team.gamesBack).toFixed(1)}</td><td className="border-l border-[#cde0d0] px-2 py-2 text-center font-semibold text-[#176537]">{divisionWins}</td><td className="px-2 py-2 text-center font-semibold text-rose-700">{divisionLosses}</td><td className="border-l border-[#cde0d0] px-3 py-2 text-center font-bold text-[#7c5a10]">{Number(team.pointsFor ?? 0).toFixed(1)}</td><td className="border-l border-[#cde0d0] px-3 py-2 text-center text-slate-500">{Number(team.pointsAgainst ?? 0).toFixed(1)}</td><td className="px-3 py-2 text-center text-slate-500">—</td></tr>; })}</tbody></table></div></section>;
  };
  const nextAway = liveFranchises.find(team => team.name === nextMatchup?.away);
  const nextHome = liveFranchises.find(team => team.name === nextMatchup?.home);
  return <div className="mx-auto max-w-5xl space-y-5 pb-8">{overview.isLoading ? <ModuleState label="Loading CVC regular-season standings…" /> : overview.error ? <ModuleState label={`CVC standings could not load: ${overview.error.message}`} /> : !liveFranchises.length ? <ModuleState label="No CVC franchises are available for the current season." /> : <><header className="px-1 pt-2"><h1 className="font-display text-4xl uppercase tracking-[0.03em] text-white sm:text-5xl">CVC Fantasy Football {seasonYear}</h1><p className="mt-1 text-sm text-white/70">Regular Season Standings — {completedGames ? `${completedGames} finalized CVC matchups` : `${seasonYear} Pre-Season`}</p></header>{nextMatchup ? <Link href="/live" className="block overflow-hidden rounded-xl bg-white shadow-[0_8px_24px_rgba(0,0,0,0.2)] transition hover:-translate-y-0.5"><div className="h-1 bg-[#dcae37]"/><div className="px-5 py-4"><div className="mb-4 flex items-center justify-between text-[11px] font-bold uppercase tracking-[0.08em]"><span className="text-[#9b7519]">{matchupSelection.isPersonal ? "Your Week 1 Matchup" : `${nextMatchup.week?.label ?? "Current"} Matchup`}</span><span className="text-[#176537]">View Live →</span></div><div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3 text-center"><div><TeamLogo name={nextMatchup.away} abbreviation={nextAway?.abbreviation} logoUrl={nextAway?.logo_url} size="md" className="mx-auto border-cvc-deep/30"/><p className="mt-2 font-display text-xl uppercase text-cvc-deep">{nextMatchup.away}</p><p className="text-xs text-slate-500">{nextAway?.record ?? "0–0"}</p></div><span className="rounded-lg border border-[#e8cf85] bg-[#fff8dd] px-3 py-2 font-display text-xl text-[#8f6913]">VS</span><div><TeamLogo name={nextMatchup.home} abbreviation={nextHome?.abbreviation} logoUrl={nextHome?.logo_url} size="md" className="mx-auto border-cvc-accent/50"/><p className="mt-2 font-display text-xl uppercase text-cvc-deep">{nextMatchup.home}</p><p className="text-xs text-slate-500">{nextHome?.record ?? "0–0"}</p></div></div></div></Link> : null}<div className="space-y-5">{orderedDivisions.map(divisionTable)}</div><CvcInjuryReport /><CvcMyTeamNews /></>}</div>;
}

function Metric({ value, label }: { value: string; label: string }) { return <div className="rounded-lg bg-cvc-tint px-3 py-3"><div className="font-display text-xl uppercase text-cvc-deep">{value}</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[0.12em] text-slate-500">{label}</div></div>; }
function ModuleState({ label }: { label: string }) { return <div className="rounded-lg border border-dashed border-cvc-deep/20 bg-cvc-tint p-6 text-center text-sm text-slate-600">{label}</div>; }

function Tank01LiveScoring() {
  const board = trpc.league.liveScoringBoard.useQuery();
  const rules = trpc.league.scoringRules.useQuery();
  const live = useCvcTank01LiveScores(board.data?.week?.weekNumber, 2026, rules.data ?? []);
  const lineupTotal = (lineup: any[]) => lineup.reduce((total, entry) => total + (getCvcLivePoints(live.scores, entry.player.display_name, entry.player.position, entry.player.nfl_team) ?? 0), 0);
  const hasLiveData = Object.keys(live.scores).length > 0;
  return <div className="space-y-6"><Card title="Tank01 live scoreboard" action={<span className="text-[10px] font-bold uppercase tracking-[0.14em] text-cvc-accent">{live.isPolling ? "Live · 30s refresh" : "Awaiting active NFL games"}</span>}>{board.isLoading || rules.isLoading ? <ModuleState label="Loading CVC lineups and scoring rules…" /> : board.error || rules.error ? <ModuleState label={`CVC live scoring could not load: ${(board.error ?? rules.error)?.message}`} /> : !board.data?.week ? <ModuleState label="No CVC live or upcoming scoring week is configured." /> : <><p className="mb-4 text-sm text-slate-500">{board.data.week.label} uses Tank01 game schedules and box scores. Active games refresh every 30 seconds; Tank01 remains the only score source.</p><div className="grid gap-4 md:grid-cols-2">{board.data.matchups.map(matchup => { const away = hasLiveData ? lineupTotal(matchup.awayLineup) : Number(matchup.awayScore); const home = hasLiveData ? lineupTotal(matchup.homeLineup) : Number(matchup.homeScore); return <div className="cvc-matchup" key={matchup.id}><div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-[0.13em] text-slate-500"><span>{board.data.week?.label}</span><StatusPill state={live.isPolling ? "live" : matchup.resultState} /></div><div className="mt-5 grid grid-cols-[1fr_auto_1fr] items-center gap-3"><div><p className="font-display text-xl uppercase text-cvc-deep">{matchup.away}</p><p className="mt-1 text-xs text-slate-500">{matchup.awayLineup.length} configured starters</p></div><strong className="font-display text-3xl text-cvc-deep">{away.toFixed(1)}<span className="mx-1 text-cvc-accent">:</span>{home.toFixed(1)}</strong><div className="text-right"><p className="font-display text-xl uppercase text-cvc-deep">{matchup.home}</p><p className="mt-1 text-xs text-slate-500">{matchup.homeLineup.length} configured starters</p></div></div></div>; })}</div><div className="mt-6 rounded-lg border border-dashed border-cvc-deep/20 bg-cvc-tint p-4 text-sm text-slate-600"><strong className="text-cvc-deep">Tank01 status:</strong> {live.error ? live.error : live.lastUpdated ? `updated ${live.lastUpdated.toLocaleTimeString()}` : "Monitoring the NFL schedule for an active game window."}</div></>}</Card><div className="grid gap-6 lg:grid-cols-3"><Card title="Live data status"><Metric value={live.isPolling ? "Polling" : "Standby"} label="Tank01 game feed" /></Card><Card title="Scoring status"><Metric value={`${rules.data?.length ?? 0} rules`} label="CVC scoring system" /></Card><Card title="Finalization"><Metric value="Tank01 only" label="No commissioner entry" /></Card></div></div>;
}

function MatchupBoard({ liveOnly = false }: { liveOnly?: boolean }) {
  const rows = liveOnly ? matchups.filter(item => item.state === "Live" || item.state === "Upcoming") : matchups;
  return <div className="grid gap-4 md:grid-cols-2">{rows.map((matchup, index) => <div className="cvc-matchup" key={`${matchup.week}-${index}`}><div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-[0.13em] text-slate-500"><span>Week {matchup.week}</span><StatusPill state={matchup.state} /></div><div className="mt-5 grid grid-cols-[1fr_auto_1fr] items-center gap-3"><div><p className="font-display text-xl uppercase text-cvc-deep">{matchup.away}</p><p className="mt-1 text-xs text-slate-500">Away</p></div><strong className="font-display text-3xl text-cvc-deep">{matchup.awayScore || "–"}<span className="mx-1 text-cvc-accent">:</span>{matchup.homeScore || "–"}</strong><div className="text-right"><p className="font-display text-xl uppercase text-cvc-deep">{matchup.home}</p><p className="mt-1 text-xs text-slate-500">Home</p></div></div></div>)}</div>;
}

function LiveScoring() { const overview = trpc.league.overview.useQuery(); const provider = trpc.league.nflProviderStatus.useQuery(); const liveRows = overview.data?.matchups.filter(row => row.result_state === "live") ?? []; const upcomingRows = overview.data?.matchups.filter(row => row.result_state === "upcoming") ?? []; const focusWeek = (liveRows[0] ?? upcomingRows[0])?.week?.week_number; const rows = (liveRows.length ? liveRows : upcomingRows).filter(row => row.week?.week_number === focusWeek); const focusLabel = (liveRows[0] ?? upcomingRows[0])?.week?.label ?? "Current week"; return <div className="space-y-6"><Card title="Current scoreboard" action={<span className="text-[10px] font-bold uppercase tracking-[0.14em] text-cvc-accent">{provider.data?.configured ? provider.data.provider : "Provider ready"}</span>}>{overview.isLoading ? <ModuleState label="Loading CVC matchup board…" /> : overview.error ? <ModuleState label={`CVC matchup board could not load: ${overview.error.message}`} /> : rows.length ? <><p className="mb-4 text-sm text-slate-500">Showing {focusLabel} — the current live week or next scheduled CVC slate.</p><div className="grid gap-4 md:grid-cols-2">{rows.map(row => <div className="cvc-matchup" key={row.id}><div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-[0.13em] text-slate-500"><span>{row.week?.label ?? "Current week"}</span><StatusPill state={row.result_state} /></div><div className="mt-5 grid grid-cols-[1fr_auto_1fr] items-center gap-3"><div><p className="font-display text-xl uppercase text-cvc-deep">{row.away}</p><p className="mt-1 text-xs text-slate-500">Away</p></div><strong className="font-display text-3xl text-cvc-deep">{Number(row.away_score).toFixed(1)}<span className="mx-1 text-cvc-accent">:</span>{Number(row.home_score).toFixed(1)}</strong><div className="text-right"><p className="font-display text-xl uppercase text-cvc-deep">{row.home}</p><p className="mt-1 text-xs text-slate-500">Home</p></div></div></div>)}</div></> : <ModuleState label="No CVC matchup is currently live or upcoming." />}<div className="mt-6 rounded-lg border border-dashed border-cvc-deep/20 bg-cvc-tint p-4 text-sm text-slate-600"><strong className="text-cvc-deep">Provider-neutral adapter:</strong> {provider.error ? `Provider status could not load: ${provider.error.message}` : provider.data?.message ?? "Checking provider configuration…"}</div></Card><div className="grid gap-6 lg:grid-cols-3"><Card title="Live data status"><Metric value={provider.data?.configured ? "Connected" : "Not connected"} label="NFL data provider" /></Card><Card title="Scoring status"><Metric value="Configurable" label="CVC rule engine" /></Card><Card title="Correction window"><Metric value="Commissioner" label="Override authority" /></Card></div></div>; }

function RosterTable({ editable = false }: { editable?: boolean }) { return <div className="overflow-x-auto"><table className="cvc-table"><thead><tr><th>Slot</th><th>Player</th><th>NFL team</th><th>Projection</th><th>Status</th>{editable ? <th /> : null}</tr></thead><tbody>{rosterPreview.map(player => <tr key={player.slot}><td><span className="cvc-slot">{player.slot}</span></td><td className="font-semibold">{player.player}</td><td>{player.team}</td><td>{player.projection}</td><td><StatusPill state={player.status} /></td>{editable ? <td className="text-right"><button className="cvc-mini-button">Move</button></td> : null}</tr>)}</tbody></table></div>; }
function RosterDataTable({ data, editable = false }: { data: { id: string; assigned_slot_code: string | null; roster_state: string; player: { id: string; display_name: string; nfl_team: string | null; status: string; position: string | null } | null; contract?: { salary: number | string; source_marker: string | null; expires_year: number | null; contract_status: string } | null; rights?: { right_type: string }[] }[]; editable?: boolean }) { return data.length ? <div className="overflow-x-auto"><table className="cvc-table"><thead><tr><th>Slot</th><th>Player</th><th>NFL team</th><th>Position</th><th>Salary</th><th>Contract / right</th><th>Status</th>{editable ? <th /> : null}</tr></thead><tbody>{data.map(item => <tr key={item.id}><td><span className="cvc-slot">{item.assigned_slot_code ?? item.roster_state}</span></td><td className="font-semibold">{item.player ? <Link href={`/player/${item.player.id}`} className="text-cvc-deep hover:text-cvc-accent">{item.player.display_name}</Link> : "Player unavailable"}</td><td>{item.player?.nfl_team ?? "—"}</td><td>{item.player?.position ?? "—"}</td><td>{item.contract ? `$${Number(item.contract.salary).toFixed(0)}` : "—"}</td><td className="capitalize">{item.rights?.length ? item.rights.map(right => right.right_type.replaceAll("_", " ")).join(", ") : item.contract?.source_marker ?? item.contract?.expires_year ?? "—"}</td><td><StatusPill state={item.player?.status ?? item.roster_state} /></td>{editable ? <td className="text-right"><button className="cvc-mini-button">Move</button></td> : null}</tr>)}</tbody></table></div> : <ModuleState label="No active player assignments are configured for this franchise." />; }

function LineupSlotEditor({ assignments }: { assignments: any[] }) { const utils = trpc.useUtils(); const slots = trpc.league.rosterSlots.useQuery(); const update = trpc.league.setLineupSlot.useMutation({ onSuccess: () => { utils.league.franchiseRoster.invalidate(); utils.league.activity.invalidate(); } }); if (slots.isLoading) return <ModuleState label="Loading configured CVC lineup slots…" />; if (slots.error) return <ModuleState label={`CVC lineup slots could not load: ${slots.error.message}`} />; return <div className="mt-6 rounded-lg border border-cvc-deep/10 bg-cvc-tint p-4"><p className="font-semibold text-cvc-deep">Assign lineup slots</p><p className="mt-1 text-xs text-slate-500">Eligible slots and capacity come from current commissioner configuration. Each change is saved immediately.</p><div className="mt-4 grid gap-3 md:grid-cols-2">{assignments.filter(assignment => assignment.player).map(assignment => { const options = (slots.data ?? []).filter(slot => !slot.eligible_positions?.length || !assignment.player?.position || slot.eligible_positions.includes(assignment.player.position)); return <label key={assignment.id} className="rounded-md bg-white px-3 py-2 text-sm">{assignment.player?.id ? <Link href={`/player/${assignment.player.id}`} className="block truncate font-semibold text-cvc-deep hover:text-cvc-accent">{assignment.player.display_name}</Link> : <span className="block truncate font-semibold text-cvc-deep">{assignment.player?.display_name}</span>}<select value={assignment.assigned_slot_code ?? ""} disabled={update.isPending} onChange={event => event.target.value && update.mutate({ assignmentId: assignment.id, slotCode: event.target.value })} className="mt-2 w-full rounded border border-slate-200 bg-white px-2 py-1.5 text-xs text-cvc-deep"><option value="">Choose slot</option>{options.map(slot => <option key={slot.id} value={slot.code}>{slot.label}</option>)}</select></label>; })}</div>{update.error ? <p className="mt-3 text-sm font-medium text-red-700">{update.error.message}</p> : null}</div>; }

function Lineup() { const mine = trpc.league.myFranchise.useQuery(); const roster = trpc.league.franchiseRoster.useQuery({ franchiseId: mine.data?.id ?? "00000000-0000-0000-0000-000000000000" }, { enabled: Boolean(mine.data?.id) }); return <div className="grid gap-6 xl:grid-cols-[1.35fr_0.65fr]"><Card title={`${mine.data?.name ?? "My franchise"} · lineup`}>{mine.isLoading || roster.isLoading ? <ModuleState label="Loading secured owner lineup…" /> : mine.error ? <ModuleState label="Your account is authenticated but does not yet have an assigned CVC franchise." /> : <><div className="mb-5"><p className="text-sm text-slate-500">CVC owner workspace uses role-protected roster actions. Slot changes are saved and audited immediately.</p></div><RosterDataTable data={roster.data?.players ?? []} /><LineupSlotEditor assignments={roster.data?.players ?? []} /></>}</Card><div className="space-y-6"><Card title="Matchup outlook"><p className="font-display text-4xl uppercase text-cvc-deep">Live data <span className="text-cvc-accent">/</span> ready</p><p className="mt-2 text-sm text-slate-500">Scoring projections appear when a CVC NFL data provider is connected.</p></Card><Card title="Lineup controls"><div className="space-y-3 text-sm text-slate-600"><p>Lineup locks, eligibility, and roster-slot limits come from commissioner configuration.</p><Link className="cvc-text-link" href="/settings">Review CVC roster rules <ChevronRight size={15} /></Link></div></Card></div></div>; }

function DraftManager({ board }: { board: any }) { const { owner } = useCvcOwnerAuth(); const utils = trpc.useUtils(); const overview = trpc.league.overview.useQuery(undefined, { enabled: ["commissioner", "administrator"].includes(owner?.role ?? "") }); const [label, setLabel] = useState(board?.label ?? "CVC Rookie Draft"); const [status, setStatus] = useState(board?.status ?? "setup"); const [round, setRound] = useState("1"); const [pickNumber, setPickNumber] = useState(""); const [franchiseId, setFranchiseId] = useState(""); const save = trpc.league.saveDraft.useMutation({ onSuccess: () => utils.league.draftBoard.invalidate() }); const savePick = trpc.league.saveDraftPick.useMutation({ onSuccess: () => { setPickNumber(""); setFranchiseId(""); utils.league.draftBoard.invalidate(); } }); if (!["commissioner", "administrator"].includes(owner?.role ?? "")) return <Card title="Draft controls"><p className="text-sm leading-6 text-slate-600">{board ? `${board.draft_type} draft · ${board.pick_timer_seconds ?? "No"}-second timer · no lottery` : "Draft settings load from CVC configuration."}</p></Card>; return <Card title="Commissioner draft control"><div className="space-y-3"><p className="text-sm leading-6 text-slate-600">Configure the CVC rookie draft and add transparent pick ownership before selections begin. CVC does not use a draft lottery.</p><input value={label} onChange={event => setLabel(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep" placeholder="Draft label" /><select value={status} onChange={event => setStatus(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep"><option value="setup">Setup</option><option value="live">Live</option><option value="paused">Paused</option><option value="complete">Complete</option></select><button type="button" onClick={() => save.mutate({ label, draftType: "rookie", status: status as "setup" | "live" | "paused" | "complete", lotteryEnabled: false, pickTimerSeconds: null, startsAt: null })} disabled={!label.trim() || save.isPending} className="cvc-button-compact">{save.isPending ? "Saving…" : "Save rookie draft"}</button>{board ? <div className="border-t border-slate-200 pt-3"><p className="mb-2 text-xs font-bold uppercase tracking-[0.12em] text-slate-500">Add pick ownership</p><div className="grid gap-2"><input value={round} onChange={event => setRound(event.target.value.replace(/\D/g, ""))} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep" placeholder="Round" /><input value={pickNumber} onChange={event => setPickNumber(event.target.value.replace(/\D/g, ""))} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep" placeholder="Overall pick number" /><select value={franchiseId} onChange={event => setFranchiseId(event.target.value)} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep"><option value="">Choose franchise</option>{overview.data?.franchises.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}</select><button type="button" disabled={!pickNumber || !franchiseId || savePick.isPending} onClick={() => savePick.mutate({ draftId: board.id, roundNumber: Number(round), pickNumber: Number(pickNumber), franchiseId })} className="cvc-button-compact">Add pick</button></div></div> : null}{save.error || savePick.error ? <p className="text-sm font-medium text-red-700">{save.error?.message ?? savePick.error?.message}</p> : null}</div></Card>; }

function Draft({ mode }: { mode: "hub" | "lottery" | "recap" }) { const board = trpc.league.draftBoard.useQuery(); const title = mode === "lottery" ? "Draft lottery order" : mode === "recap" ? "Latest draft recap" : "CVC draft board"; const rows = board.data?.picks ?? []; return <div className="grid gap-6 xl:grid-cols-[1.3fr_0.7fr]"><Card title={title}>{board.isLoading ? <ModuleState label="Loading CVC draft board…" /> : rows.length ? <div className="overflow-x-auto"><table className="cvc-table"><thead><tr><th>Pick</th><th>Franchise</th><th>Selection</th><th>Note</th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td><span className="cvc-slot">{row.round_number}.{String(row.pick_number).padStart(2, "0")}</span></td><td className="font-semibold">{row.currentFranchise}</td><td>{mode === "recap" ? "Historical selection placeholder" : row.pick_status === "open" ? "Open selection" : "Selection recorded"}</td><td>{row.notes ?? (row.is_protected ? "Protected pick" : "CVC pick")}</td></tr>)}</tbody></table></div> : <ModuleState label="No draft picks have been configured yet." />}</Card><div className="space-y-6"><DraftManager board={board.data} /><Card title="Draft modules"><div className="space-y-3">{["Live draft board", "Pick protection ledger", "Lottery logic", "Draft recap archive"].map((item, index) => <div key={item} className="flex items-center gap-3 text-sm font-medium text-cvc-deep"><span className="flex h-6 w-6 items-center justify-center rounded-full bg-cvc-tint text-[10px] font-bold text-cvc-accent">0{index + 1}</span>{item}</div>)}</div></Card></div></div>; }

function WaiverCommissionerQueue() { const utils = trpc.useUtils(); const queue = trpc.league.waiverBidQueue.useQuery(); const resolve = trpc.league.resolveFaabBid.useMutation({ onSuccess: async () => { await Promise.all([utils.league.waiverBidQueue.invalidate(), utils.league.freeAgents.invalidate(), utils.league.activity.invalidate(), utils.league.myFaabBids.invalidate()]); } }); return <div className="mb-5 rounded-lg border border-cvc-deep/10 bg-cvc-tint p-4"><p className="font-semibold text-cvc-deep">Commissioner waiver queue</p><p className="mt-1 text-xs text-slate-500">Resolve a submitted claim only after confirming the winning order and FAAB amount.</p>{queue.isLoading ? <p className="mt-3 text-sm text-slate-500">Loading pending claims…</p> : queue.data?.length ? <div className="mt-3 space-y-2">{queue.data.map((bid: any) => <div key={bid.id} className="flex flex-wrap items-center justify-between gap-2 rounded-md bg-white p-3 text-sm"><span><b className="text-cvc-deep">{bid.player?.[0]?.id ? <Link href={`/player/${bid.player[0].id}`} className="text-cvc-deep hover:text-cvc-accent">{bid.player[0].display_name}</Link> : bid.player?.[0]?.display_name}</b> · {bid.franchise?.[0]?.name} · ${bid.amount}</span><span className="flex gap-2"><button type="button" onClick={() => resolve.mutate({ bidId: bid.id, outcome: "won" })} disabled={resolve.isPending} className="cvc-mini-button">Award</button><button type="button" onClick={() => resolve.mutate({ bidId: bid.id, outcome: "lost" })} disabled={resolve.isPending} className="cvc-mini-button">Mark lost</button></span></div>)}</div> : <p className="mt-3 text-sm text-slate-500">No pending CVC waiver claims.</p>}{resolve.error ? <p className="mt-3 text-sm font-medium text-red-700">{resolve.error.message}</p> : null}</div>; }

function CommissionerAuditTimeline() { const audit = trpc.league.auditHistory.useQuery(); return <Card title="Commissioner audit timeline">{audit.isLoading ? <ModuleState label="Loading protected CVC audit history…" /> : audit.error ? <ModuleState label={audit.error.message} /> : audit.data?.length ? <div className="space-y-3">{audit.data.map((event: any) => <div key={event.id} className="border-l-2 border-cvc-accent pl-4"><p className="text-sm font-semibold text-cvc-deep">{event.summary}</p><p className="mt-1 text-xs text-slate-500">{event.actor?.[0]?.display_name ?? "CVC commissioner"} · {new Date(event.created_at).toLocaleString()} · {event.action.replaceAll("_", " ")}</p></div>)}</div> : <ModuleState label="No commissioner audit events have been recorded for this season." />}</Card>; }

function TradesDesk() { const { owner } = useCvcOwnerAuth(); const utils = trpc.useUtils(); const mine = trpc.league.myFranchise.useQuery(); const overview = trpc.league.overview.useQuery(); const [recipientId, setRecipientId] = useState(""); const [offerPlayerId, setOfferPlayerId] = useState(""); const [requestPlayerId, setRequestPlayerId] = useState(""); const [note, setNote] = useState(""); const myRoster = trpc.league.franchiseRoster.useQuery({ franchiseId: mine.data?.id ?? "00000000-0000-0000-0000-000000000000" }, { enabled: Boolean(mine.data?.id) }); const recipientRoster = trpc.league.franchiseRoster.useQuery({ franchiseId: recipientId || "00000000-0000-0000-0000-000000000000" }, { enabled: Boolean(recipientId) }); const trades = trpc.league.myTrades.useQuery(undefined, { enabled: Boolean(owner) }); const refresh = async () => { await Promise.all([utils.league.myTrades.invalidate(), utils.league.franchiseRoster.invalidate(), utils.league.activity.invalidate()]); }; const propose = trpc.league.proposeTrade.useMutation({ onSuccess: async () => { setRecipientId(""); setOfferPlayerId(""); setRequestPlayerId(""); setNote(""); await refresh(); } }); const respond = trpc.league.respondToTrade.useMutation({ onSuccess: refresh }); const execute = trpc.league.executeTrade.useMutation({ onSuccess: refresh }); const isCommissioner = ["commissioner", "administrator"].includes(owner?.role ?? ""); if (!owner) return <div className="grid gap-6 lg:grid-cols-[1fr_0.7fr]"><Card title="CVC Trade Desk"><ModuleState label="Sign in with your CVC owner PIN to propose, accept, or review trades." /></Card><Card title="Trade policy"><p className="text-sm leading-6 text-slate-600">Trade actions are limited to authenticated CVC owners. Accepted proposals require commissioner execution and an audit record.</p></Card></div>; return <div className="grid gap-6 xl:grid-cols-[1.25fr_0.75fr]"><Card title="Propose a player trade">{mine.isLoading || overview.isLoading ? <ModuleState label="Loading CVC franchises and rosters…" /> : mine.error ? <ModuleState label={mine.error.message} /> : <div className="grid gap-4"><div className="rounded-lg bg-cvc-tint p-4 text-sm text-slate-600">Proposing as <b className="text-cvc-deep">{mine.data?.name}</b>. Submit one player each way; the recipient must accept before a commissioner executes the trade.</div><label className="cvc-field"><span>Recipient franchise</span><select value={recipientId} onChange={event => { setRecipientId(event.target.value); setRequestPlayerId(""); }}><option value="">Choose franchise</option>{overview.data?.franchises.filter(team => team.id !== mine.data?.id).map(team => <option key={team.id} value={team.id}>{team.name}</option>)}</select></label><label className="cvc-field"><span>You send</span><select value={offerPlayerId} onChange={event => setOfferPlayerId(event.target.value)}><option value="">Choose your roster player</option>{myRoster.data?.players.map(item => item.player ? <option key={item.id} value={item.player.id}>{item.player.display_name} · {item.player.position ?? "—"}</option> : null)}</select></label><label className="cvc-field"><span>You receive</span><select value={requestPlayerId} onChange={event => setRequestPlayerId(event.target.value)} disabled={!recipientId}><option value="">Choose recipient player</option>{recipientRoster.data?.players.map(item => item.player ? <option key={item.id} value={item.player.id}>{item.player.display_name} · {item.player.position ?? "—"}</option> : null)}</select></label><label className="cvc-field"><span>Optional note</span><textarea value={note} onChange={event => setNote(event.target.value)} placeholder="Add a commissioner-facing note if needed." /></label><button type="button" disabled={!recipientId || !offerPlayerId || !requestPlayerId || propose.isPending} onClick={() => propose.mutate({ recipientFranchiseId: recipientId, offerPlayerIds: [offerPlayerId], requestPlayerIds: [requestPlayerId], note: note.trim() || undefined })} className="cvc-button w-fit disabled:cursor-not-allowed disabled:opacity-50">{propose.isPending ? "Submitting…" : "Submit trade proposal"}</button>{propose.error ? <p className="text-sm font-medium text-red-700">{propose.error.message}</p> : null}</div>}</Card><div className="space-y-6"><Card title="Trade status">{trades.isLoading ? <ModuleState label="Loading CVC trades…" /> : trades.data?.length ? <div className="space-y-3">{trades.data.map((trade: any) => { const proposer = trade.proposer?.[0]; const recipient = trade.recipient?.[0]; const isRecipient = recipient?.id === mine.data?.id; const isProposer = proposer?.id === mine.data?.id; return <div key={trade.id} className="rounded-lg border border-slate-100 p-4"><div className="flex items-start justify-between gap-3"><p className="text-sm font-semibold text-cvc-deep">{proposer?.name} ↔ {recipient?.name}</p><StatusPill state={trade.status} /></div><p className="mt-2 text-xs text-slate-500">{trade.assets?.map((asset: any) => asset.player?.[0]?.display_name).filter(Boolean).join(" · ") || "Player assets pending"}</p>{trade.note ? <p className="mt-2 text-xs italic text-slate-500">{trade.note}</p> : null}{trade.status === "proposed" ? <div className="mt-3 flex flex-wrap gap-2">{isRecipient ? <><button onClick={() => respond.mutate({ tradeId: trade.id, response: "accepted" })} className="cvc-mini-button">Accept</button><button onClick={() => respond.mutate({ tradeId: trade.id, response: "rejected" })} className="cvc-mini-button">Reject</button></> : null}{isProposer ? <button onClick={() => respond.mutate({ tradeId: trade.id, response: "cancelled" })} className="cvc-mini-button">Cancel</button> : null}</div> : null}{trade.status === "accepted" && isCommissioner ? <button onClick={() => execute.mutate({ tradeId: trade.id })} className="cvc-mini-button mt-3">Execute trade</button> : null}</div>; })}</div> : <ModuleState label="No CVC trade proposals are currently open." />}</Card><Card title="Trade governance"><p className="text-sm leading-6 text-slate-600">CVC validates player ownership at proposal and execution. An accepted trade is not final until a commissioner executes it, creating both transaction and audit records.</p></Card></div></div>; }

function Transactions({ kind }: { kind: "transactions" | "trades" | "free-agents" }) {
  if (kind === "free-agents") return <CvcWrcFreeAgents />;
  if (kind === "transactions") return <CvcWrcTransactions />;
  const activity = trpc.league.activity.useQuery();
  const { owner } = useCvcOwnerAuth();
  const [playerSearch, setPlayerSearch] = useState("");
  const [playerPosition, setPlayerPosition] = useState("");
  const [claimPlayerId, setClaimPlayerId] = useState("");
  const [claimAmount, setClaimAmount] = useState("0");
  const [waiverLabel, setWaiverLabel] = useState("");
  const [waiverClosesAt, setWaiverClosesAt] = useState("");
  const freeAgentInput = useMemo(() => ({ search: playerSearch.trim() || undefined, position: playerPosition || undefined, limit: 75 }), [playerPosition, playerSearch]);
  const freeAgents = trpc.league.freeAgents.useQuery(freeAgentInput, { enabled: false });
  const waiver = trpc.league.waiverStatus.useQuery(undefined, { enabled: false });
  const myWaiverBids = trpc.league.myFaabBids.useQuery(undefined, { enabled: false });
  const utils = trpc.useUtils();
  const submitClaim = trpc.league.submitFaabBid.useMutation({ onSuccess: async () => { setClaimPlayerId(""); setClaimAmount("0"); await Promise.all([utils.league.myFaabBids.invalidate(), utils.league.activity.invalidate()]); } });
  const createWaiver = trpc.league.createWaiverPeriod.useMutation({ onSuccess: async () => { setWaiverLabel(""); setWaiverClosesAt(""); await utils.league.waiverStatus.invalidate(); } });
  const heading = kind === "trades" ? "Trade desk" : "League activity";
  const filtered = (activity.data ?? []).filter(item => kind === "trades" ? item.transaction_type === "trade" : true);
  const isFreeAgents = false;

  return <div className="grid gap-6 xl:grid-cols-[1.25fr_0.75fr]">
    <Card title={heading}>
      {isFreeAgents ? <>
        <p className="mb-5 text-sm leading-6 text-slate-600">This is the live CVC player pool: any player without a current roster assignment appears here. Search the synchronized pool by name or position. A Protections release is immediately eligible as an unrestricted free agent and can later be filtered into the regular auction pool.</p>
        <div className="mb-5 grid gap-3 sm:grid-cols-[1fr_150px]"><input value={playerSearch} onChange={event => setPlayerSearch(event.target.value)} placeholder="Search player name" className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep outline-none focus:border-cvc-accent" /><select value={playerPosition} onChange={event => setPlayerPosition(event.target.value)} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep outline-none focus:border-cvc-accent"><option value="">All positions</option>{["QB", "RB", "WR", "TE", "K", "DST"].map(position => <option key={position} value={position}>{position}</option>)}</select></div>
        {owner?.franchise ? <div className="mb-5 rounded-lg border border-cvc-deep/10 bg-cvc-tint p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="font-semibold text-cvc-deep">FAAB waiver claim</p><p className="mt-1 text-xs text-slate-500">{waiver.data?.period ? `${waiver.data.period.label} closes ${new Date(waiver.data.period.closes_at).toLocaleString()}.` : "No CVC waiver period is currently open."}</p></div><span className="text-xs font-bold uppercase tracking-[0.12em] text-cvc-accent">{myWaiverBids.data?.filter(bid => bid.status === "pending").length ?? 0} pending</span></div>{waiver.data?.period ? <div className="mt-4 grid gap-3 sm:grid-cols-[1fr_120px_auto]"><select value={claimPlayerId} onChange={event => setClaimPlayerId(event.target.value)} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep"><option value="">Choose a free agent</option>{freeAgents.data?.map(player => <option key={player.id} value={player.id}>{player.display_name} · {player.position ?? "—"} · {player.nfl_team ?? "FA"}</option>)}</select><input value={claimAmount} onChange={event => setClaimAmount(event.target.value.replace(/\D/g, ""))} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep" inputMode="numeric" placeholder="FAAB bid" /><button type="button" disabled={!claimPlayerId || submitClaim.isPending} onClick={() => submitClaim.mutate({ playerId: claimPlayerId, amount: Number(claimAmount), priority: 1 })} className="cvc-button-compact disabled:cursor-not-allowed disabled:opacity-50">{submitClaim.isPending ? "Submitting…" : "Submit claim"}</button></div> : null}{submitClaim.error ? <p className="mt-3 text-sm font-medium text-red-700">{submitClaim.error.message}</p> : null}{submitClaim.isSuccess ? <p className="mt-3 text-sm font-medium text-emerald-700">Your CVC waiver claim was submitted for commissioner resolution.</p> : null}</div> : null}
        {["commissioner", "administrator"].includes(owner?.role ?? "") ? <WaiverCommissionerQueue /> : null}
        {freeAgents.isLoading ? <ModuleState label="Loading CVC free-agent pool…" /> : freeAgents.error ? <ModuleState label={freeAgents.error.message} /> : freeAgents.data?.length ? <div className="overflow-x-auto"><table className="cvc-table"><thead><tr><th>Player</th><th>Position</th><th>NFL team</th><th>Status</th></tr></thead><tbody>{freeAgents.data.map(player => <tr key={player.id}><td className="font-semibold"><Link href={`/player/${player.id}`} className="text-cvc-deep hover:text-cvc-accent">{player.display_name}</Link></td><td>{player.position ?? "—"}</td><td>{player.nfl_team ?? "—"}</td><td><StatusPill state={player.status} /></td></tr>)}</tbody></table></div> : <ModuleState label="No CVC players are currently unrostered. Released players will appear here immediately." />}
      </> : activity.isLoading ? <ModuleState label="Loading CVC activity ledger…" /> : filtered.length ? <div className="divide-y divide-slate-100">{filtered.map(item => <div key={item.id} className="flex gap-4 py-4 first:pt-0 last:pb-0"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-cvc-tint text-xs font-bold text-cvc-accent">{item.transaction_type.slice(0, 2).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold capitalize text-cvc-deep">{item.transaction_type.replace("_", " ")}</p><p className="mt-1 text-sm text-slate-600">{item.summary}</p><p className="mt-1.5 text-xs text-slate-400">{new Date(item.occurred_at).toLocaleString()}</p></div><StatusPill state={item.status} /></div>)}</div> : <ModuleState label={kind === "trades" ? "No CVC trades have been recorded yet." : "No CVC transaction activity has been recorded yet."} />}
    </Card>
    <div className="space-y-6"><Card title={isFreeAgents ? "Claim workflow" : "Commissioner controls"}>{isFreeAgents && ["commissioner", "administrator"].includes(owner?.role ?? "") ? <div className="space-y-3"><p className="text-sm leading-6 text-slate-600">Open an immediate CVC waiver period when claims should begin. Owners can submit bids only while this window is open.</p><input value={waiverLabel} onChange={event => setWaiverLabel(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep" placeholder="Waiver period label" /><label className="block text-xs font-semibold uppercase tracking-[0.12em] text-slate-500">Close date and time<input type="datetime-local" value={waiverClosesAt} onChange={event => setWaiverClosesAt(event.target.value)} className="mt-2 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep" /></label><button type="button" disabled={!waiverLabel.trim() || !waiverClosesAt || createWaiver.isPending} onClick={() => createWaiver.mutate({ label: waiverLabel.trim(), opensAt: new Date().toISOString(), closesAt: new Date(waiverClosesAt).toISOString() })} className="cvc-button-compact disabled:cursor-not-allowed disabled:opacity-50">{createWaiver.isPending ? "Opening…" : "Open waiver period"}</button>{createWaiver.error ? <p className="text-sm font-medium text-red-700">{createWaiver.error.message}</p> : null}</div> : <><p className="text-sm leading-6 text-slate-600">{isFreeAgents ? "Commissioners open waiver periods and resolve submitted FAAB claims. The Auction Room separately excludes rookie-designated contracts from the regular auction pool." : "Review and override status from the protected commissioner area. All decisions receive an audit record."}</p><Link href="/settings" className="cvc-text-link mt-5">Open configuration <ChevronRight size={15} /></Link></>}</Card>{["commissioner", "administrator"].includes(owner?.role ?? "") ? <CommissionerAuditTimeline /> : null}<Card title="Audit ready"><div className="flex items-center gap-3"><ShieldCheck className="text-cvc-accent" /><p className="text-sm text-slate-600">Every dynamic CVC action includes an actor, timestamp, source, and commissioner note.</p></div></Card></div>
  </div>;
}

function Tank01ScoringNotice() { return <Card title="Automatic scoring"><div className="rounded-lg border border-cvc-accent/30 bg-cvc-tint p-4"><p className="font-semibold text-cvc-deep">Tank01 controls live scores and final results.</p><p className="mt-2 text-sm leading-6 text-slate-600">CVC does not accept commissioner-entered scores. The scheduled Tank01 synchronization will update player scoring, matchup outcomes, standings, and the audit trail automatically.</p></div></Card>; }

function ScheduleResults() {
  const overview = trpc.league.overview.useQuery();
  const rows = [...(overview.data?.matchups ?? [])].sort((a, b) => Number(a.week?.week_number ?? 0) - Number(b.week?.week_number ?? 0));
  const weekGroups = rows.reduce<Record<string, typeof rows>>((groups, row) => {
    const key = String(row.week?.week_number ?? 0);
    (groups[key] ??= []).push(row);
    return groups;
  }, {});
  const orderedWeeks = Object.entries(weekGroups).sort(([a], [b]) => Number(a) - Number(b));

  return <div className="grid gap-6 xl:grid-cols-[1.28fr_0.72fr]"><Card title="CVC 2026 schedule board">{overview.isLoading ? <ModuleState label="Loading imported CVC 2026 matchups…" /> : overview.error ? <ModuleState label={`CVC schedule could not load: ${overview.error.message}`} /> : orderedWeeks.length ? <div className="space-y-8">{orderedWeeks.map(([weekNumber, matchupsForWeek]) => <section key={weekNumber}><div className="mb-4 flex items-end justify-between border-b border-cvc-deep/10 pb-3"><div><p className="cvc-eyebrow">Regular season</p><h2 className="mt-1 font-display text-3xl uppercase text-cvc-deep">{matchupsForWeek[0]?.week?.label ?? `Week ${weekNumber}`}</h2></div><span className="text-[10px] font-bold uppercase tracking-[0.13em] text-slate-500">{matchupsForWeek.length} matchups</span></div><div className="grid gap-4 md:grid-cols-2">{matchupsForWeek.map(row => <div key={row.id} className="cvc-matchup"><div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-[0.13em] text-slate-500"><span>{row.week?.label ?? `Week ${weekNumber}`}</span><StatusPill state={row.result_state} /></div><div className="mt-5 grid grid-cols-[1fr_auto_1fr] items-center gap-3"><div><p className="font-display text-xl uppercase text-cvc-deep">{row.away}</p><p className="mt-1 text-xs text-slate-500">Away</p></div><strong className="font-display text-3xl text-cvc-deep">{Number(row.away_score).toFixed(1)}<span className="mx-1 text-cvc-accent">:</span>{Number(row.home_score).toFixed(1)}</strong><div className="text-right"><p className="font-display text-xl uppercase text-cvc-deep">{row.home}</p><p className="mt-1 text-xs text-slate-500">Home</p></div></div></div>)}</div></section>)}</div> : <ModuleState label="No imported CVC matchups are available for this season." />}</Card><div className="space-y-6"><Tank01ScoringNotice /><Card title="Season structure"><p className="text-sm leading-6 text-slate-600">The 2026 CVC regular season includes fourteen imported weeks and seventy Tank01-scored matchups across the East and West divisions.</p></Card><Card title="Schedule source"><div className="rounded-lg border border-dashed border-cvc-deep/20 bg-cvc-tint p-4"><p className="text-sm font-semibold text-cvc-deep">2026 workbook import</p><p className="mt-1 text-xs leading-5 text-slate-500">Matchups are live CVC records. Tank01 will supply scoring and result status automatically.</p></div></Card></div></div>;
}

function Rundown() { return <div className="grid gap-6 lg:grid-cols-[1.4fr_0.6fr]"><Card title="Welcome to CVC"><div className="rounded-xl bg-cvc-deep p-7 text-white"><span className="cvc-eyebrow text-cvc-accent">Commissioner message</span><h2 className="mt-3 font-display text-4xl uppercase leading-none tracking-[0.04em]">The league is<br />ready for you.</h2><p className="mt-4 max-w-xl text-sm leading-6 text-white/70">CVC starts with a complete league operating system. When the rules and franchise details arrive, they can be entered through the commissioner console rather than built into site code.</p><Link href="/settings" className="cvc-button-light mt-6">Open commissioner setup <ArrowRight size={15} /></Link></div></Card><Card title="Setup progress"><div className="space-y-4">{setupAreas.map((item, index) => <div className="flex gap-3" key={item.title}><span className="font-display text-2xl text-cvc-accent">{item.icon}</span><div><p className="text-sm font-semibold text-cvc-deep">{item.title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{item.detail}</p></div>{index === 0 ? <StatusPill state="Ready" /> : null}</div>)}</div></Card></div>; }

function NewsOrPlayer({ kind }: { kind: "news" | "player" }) { const [playerSearch, setPlayerSearch] = useState(""); const [playerPosition, setPlayerPosition] = useState(""); const directoryInput = useMemo(() => ({ search: playerSearch.trim() || undefined, position: playerPosition || undefined, limit: 75 }), [playerPosition, playerSearch]); const players = trpc.league.playerDirectory.useQuery(directoryInput); const provider = trpc.league.nflProviderStatus.useQuery(); return <div className="grid gap-6 lg:grid-cols-[1fr_0.75fr]"><Card title={kind === "player" ? "Player directory" : "Player news feed"}>{kind === "player" ? <div className="mb-5 grid gap-3 sm:grid-cols-[1fr_150px]"><input value={playerSearch} onChange={event => setPlayerSearch(event.target.value)} placeholder="Search player name" className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep outline-none focus:border-cvc-accent" /><select value={playerPosition} onChange={event => setPlayerPosition(event.target.value)} className="rounded-md border border-slate-200 bg-white px-3 py-2 text-sm text-cvc-deep outline-none focus:border-cvc-accent"><option value="">All positions</option>{["QB", "RB", "WR", "TE", "K", "DST"].map(position => <option key={position} value={position}>{position}</option>)}</select></div> : null}{players.isLoading ? <ModuleState label="Loading CVC player records…" /> : players.data?.length ? <div className="space-y-3">{players.data.map(item => <Link href={`/player/${item.id}`} className="block rounded-lg border border-slate-100 p-4 hover:border-cvc-accent" key={item.id}><div className="flex items-center justify-between"><p className="text-sm font-semibold text-cvc-deep">{item.display_name}</p><StatusPill state={item.status} /></div><p className="mt-2 text-sm leading-6 text-slate-500">{item.position ?? "Position pending"} · {item.nfl_team ?? "NFL team pending"}. {kind === "news" ? "Provider-neutral news feed will appear after the CVC source is configured." : "Open full player detail."}</p></Link>)}</div> : <ModuleState label="No CVC player records match these filters." />}</Card><Card title="Adapter status"><p className="font-display text-3xl uppercase text-cvc-deep">{provider.data?.configured ? provider.data.provider : "Not bound"}</p><p className="mt-2 text-sm leading-6 text-slate-600">{provider.data?.message ?? "The data adapter accepts normalized player, news, game, and stat records."}</p></Card></div>; }

function PlayerDetail() { const [, params] = useRoute("/player/:playerId"); const playerId = params?.playerId ?? ""; const isValid = /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(playerId); const player = trpc.league.playerDetail.useQuery({ playerId: isValid ? playerId : "00000000-0000-0000-0000-000000000000" }, { enabled: isValid }); const provider = trpc.league.nflProviderStatus.useQuery(); return <div className="grid gap-6 lg:grid-cols-[1fr_0.75fr]"><Card title="Player profile">{!isValid ? <ModuleState label="Choose a CVC player from the player directory to open detail." /> : player.isLoading ? <ModuleState label="Loading CVC player detail…" /> : player.error || !player.data ? <ModuleState label="This CVC player record was not found." /> : <div className="rounded-xl bg-cvc-tint p-7"><div className="flex items-start justify-between gap-4"><div><p className="font-display text-4xl uppercase text-cvc-deep">{player.data.display_name}</p><p className="mt-2 text-sm text-slate-600">{player.data.position ?? "Position pending"} · {player.data.nfl_team ?? "NFL team pending"}</p></div><StatusPill state={player.data.status} /></div><div className="mt-6 grid grid-cols-2 gap-3"><Metric value={player.data.provider} label="Record provider" /><Metric value={player.data.external_id ?? "Pending"} label="External ID" /></div><p className="mt-6 text-sm leading-6 text-slate-600">Game logs, scoring, news, and availability will flow through the configured provider adapter while this stable CVC player ID remains constant.</p></div>}</Card><Card title="Adapter status"><p className="font-display text-3xl uppercase text-cvc-deep">{provider.data?.configured ? "Connected" : "Not bound"}</p><p className="mt-2 text-sm leading-6 text-slate-600">{provider.data?.message ?? "Checking CVC provider configuration…"}</p><Link href="/news" className="cvc-text-link mt-5">Browse CVC players <ChevronRight size={15} /></Link></Card></div>; }

function Informational({ kind }: { kind: "history" | "playoffs" | "rules" | "nfl-sites" | "money" }) { const module = pageMeta[kind]; return <div className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]"><Card title={module.title}><div className="rounded-xl bg-cvc-tint p-7"><p className="font-display text-3xl uppercase text-cvc-deep">CVC {kind === "rules" ? "rulebook" : kind === "money" ? "league ledger" : "archive module"}</p><p className="mt-4 max-w-2xl text-sm leading-6 text-slate-600">This module is foundation-ready and intentionally uses no actual CVC history, policy, or financial information. Commissioner-entered records will replace all placeholders when the league is configured.</p>{kind === "rules" ? <div className="mt-6 space-y-3">{["Scoring and roster policy", "Transactions, FAAB, and trades", "Playoffs, tiebreakers, and commissioner authority"].map((item, index) => <div className="flex items-center justify-between rounded-lg bg-white px-4 py-3 text-sm font-medium text-cvc-deep" key={item}><span>{item}</span><span className="text-xs text-slate-400">Version 0{index + 1}</span></div>)}</div> : <div className="mt-6 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-white text-cvc-accent"><BookOpen size={18} /></span><span className="text-sm font-medium text-cvc-deep">Commissioner-managed content and records</span></div>}</div></Card><Card title="Commissioner action"><p className="text-sm leading-6 text-slate-600">Use League Configuration to publish approved CVC content, define privacy settings, and establish the history or finance record model for this season.</p><Link href="/settings" className="cvc-text-link mt-5">Open configuration <ChevronRight size={15} /></Link></Card></div>; }

function Rosters() { const overview = trpc.league.overview.useQuery(); const rows = overview.data?.franchises ?? []; return <div className="grid gap-6 xl:grid-cols-[1.25fr_0.75fr]"><Card title="CVC franchises">{overview.isLoading ? <ModuleState label="Loading CVC franchise directory…" /> : rows.length ? <div className="grid gap-3 sm:grid-cols-2">{rows.map(team => <Link href={`/lineup/${team.id}`} className="cvc-franchise-card" key={team.id}><span className="h-2.5 w-2.5 rounded-full" style={{ background: team.brand_color ?? "#30d5c8" }} /><div className="min-w-0 flex-1"><p className="font-display text-xl uppercase text-cvc-deep">{team.name}</p><p className="mt-1 text-xs text-slate-500">{team.owner} · {team.division_name ?? "Unassigned"} division</p></div><ChevronRight size={17} className="text-slate-400" /></Link>)}</div> : <ModuleState label="No CVC franchises have been configured yet." />}</Card><Card title="Roster model"><p className="text-sm leading-6 text-slate-600">CVC roster slots, salary/keeper attributes, player eligibility, and owner affiliation are configuration-driven.</p><div className="mt-5"><Metric value={String(rows.length)} label="Configured franchises" /></div></Card></div>; }

function Settings() { const [active, setActive] = useState("teams"); const setup = trpc.league.setupSummary.useQuery(); const content = useMemo(() => ({ teams: ["Franchise name", "Abbreviation", "Division", "Owner membership"], scoring: ["Roster slots", "Scoring categories", "Bonuses and penalties", "Lineup locks"], schedule: ["Regular season weeks", "Matchups", "Playoff seeding", "Tiebreakers"], rules: ["Rule documents", "Version and publish date", "Public visibility", "Commissioner notes"], finance: ["League dues", "Payout schedule", "Balances", "Private access"] })[active] ?? [], [active]); return <div className="grid gap-6 xl:grid-cols-[0.38fr_1fr]"><Card title="Setup modules"><div className="space-y-1">{[["teams", "Teams & owners"], ["scoring", "Scoring & rosters"], ["schedule", "Schedule & playoffs"], ["rules", "Rules & content"], ["finance", "Finance"]].map(([key, label]) => <button key={key} className={cn("cvc-config-link", active === key && "is-active")} onClick={() => setActive(key)}>{label}<ChevronRight size={15} /></button>)}</div><div className="mt-5 rounded-lg bg-cvc-tint p-3 text-xs leading-5 text-slate-500">CVC data layer: {setup.isLoading ? "checking schema…" : `${setup.data?.filter(item => item.count > 0).length ?? 0} configured modules ready`}.</div></Card><Card title={`Configure ${active}`} action={<span className="text-[10px] font-bold uppercase tracking-[0.13em] text-cvc-accent">Commissioner form</span>}><div className="grid gap-4 sm:grid-cols-2">{content.map(label => <label key={label} className="cvc-field"><span>{label}</span><input placeholder={`Enter ${label.toLowerCase()}`} /></label>)}</div><div className="mt-6 flex flex-wrap gap-3"><button className="cvc-button-compact"><Plus size={14} /> Add placeholder</button><label className="cvc-button-secondary cursor-pointer"><Upload size={14} /> Import CSV<input className="sr-only" type="file" accept=".csv" /></label><button className="cvc-button-secondary">Download template</button></div><div className="mt-6 rounded-lg border border-dashed border-cvc-deep/20 p-4 text-sm text-slate-600"><strong className="text-cvc-deep">Connected data layer:</strong> commissioner saves validate against the CVC Supabase schema and create an audit entry. Your current account must first be mapped to a commissioner role in CVC.</div></Card></div>; }

export function PublicFranchiseLineup() { const [, params] = useRoute("/lineup/:franchiseId"); const franchiseId = params?.franchiseId ?? ""; const validId = /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(franchiseId); const roster = trpc.league.franchiseRoster.useQuery({ franchiseId: validId ? franchiseId : "00000000-0000-0000-0000-000000000000" }, { enabled: validId }); const legacy = franchises.find(item => item.id === franchiseId); const title = roster.data?.franchise.name ?? legacy?.name ?? "Franchise lineup"; return <LeagueLayout><div className="mb-8"><div className="cvc-eyebrow"><UsersRound size={14} /> Public franchise view</div><h1 className="mt-2 font-display text-5xl uppercase leading-none tracking-[0.04em] text-white sm:text-6xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-cvc-muted">Public lineup, roster, and matchup information. Owner actions remain protected.</p></div><Card title={`${title} roster`}>{roster.isLoading ? <ModuleState label="Loading CVC franchise roster…" /> : validId ? <RosterDataTable data={roster.data?.players ?? []} /> : <RosterTable />}</Card></LeagueLayout>; }

export default function LeaguePage({ kind }: { kind: PageKind }) {
  let body: React.ReactNode;
  if (kind === "standings") body = <Standings />;
  else if (kind === "live") body = <CvcWrcLiveScoring />;
  else if (kind === "lineup") body = <CvcWrcOwnerLineup />;
  else if (kind === "draft") body = <CvcWrcDraftHub />;
  else if (kind === "draft-recap") body = <CvcWrcDraftRecap />;
  else if (kind === "trades") body = <CvcWrcTrades />;
  else if (kind === "transactions" || kind === "free-agents") body = <Transactions kind={kind} />;
  else if (kind === "results") body = <CvcWrcScheduleResults />;
  else if (kind === "rundown") body = <CvcWrcRundown />;
  else if (kind === "news") body = <CvcWrcPlayerNews />;
  else if (kind === "player") body = <CvcWrcPlayerProfile />;
  else if (kind === "money") body = <CvcWrcMoney />;
  else if (kind === "rules") body = <CvcWrcRules />;
  else if (kind === "history") body = <CvcWrcHistory />;
  else if (kind === "playoffs") body = <CvcWrcPlayoffs />;
  else if (kind === "nfl-sites") body = <CvcWrcNflSites />;
  else if (kind === "rosters") body = <CvcWrcRosters />;
  else if (kind === "settings") body = <CommissionerPanel />;
  else body = <Informational kind={kind as "history" | "playoffs" | "rules" | "nfl-sites" | "money"} />;
  const usesDirectWrcWorkspace = kind === "standings" || kind === "live" || kind === "lineup" || kind === "draft" || kind === "draft-recap" || kind === "free-agents" || kind === "rosters" || kind === "transactions" || kind === "results" || kind === "rundown" || kind === "trades" || kind === "news" || kind === "player" || kind === "money" || kind === "rules" || kind === "history" || kind === "playoffs" || kind === "nfl-sites";
  return <LeagueLayout>{usesDirectWrcWorkspace ? null : <PageHeader kind={kind} />}{body}</LeagueLayout>;
}
